import {t,getLanguage,applyLanguage} from './i18n.js';
const store='fdudash.device.v1',base='http://127.0.0.1:5173';
const words={'连接你的设备':['Connect your device','Coniunge instrumentum tuum'],'校园密码和数据保存在你的设备，校园请求使用你的网络。':['Campus credentials and data stay on your device; requests use your network.','Tesserae et data in tuo instrumento manent; rete tuum adhibetur.'],'下载 Windows 连接器':['Download Windows connector','Depone connexorem Windows'],'解压后运行 Start.cmd，获取一次性配对码。':['Extract and run Start.cmd to get a one-time pairing code.','Extrahe et Start.cmd exsequere ad codicem accipiendum.'],'配对码':['Pairing code','Codex coniunctionis'],'连接':['Connect','Coniunge'],'无法连接，请启动本机连接器、允许浏览器访问本机网络，并检查配对码。':['Could not connect. Start the local connector, allow local network access, and check the pairing code.','Coniunctio defecit. Connexorem localem incipe et codicem verifica.'],'在当前设备运行连接器后，即可读取个人校园信息。':['Run the connector on this device to access personal campus information.','Connexore in hoc instrumento incepto, data universitatis legere potes.'],'正在连接…':['Connecting…','Coniungitur…']};
const tr=s=>getLanguage()==='en'?words[s]?.[0]||t(s):getLanguage()==='la'?words[s]?.[1]||t(s):t(s);let config;
function prompt(){document.body.classList.add('device-required');const root=document.createElement('section');root.className='card device-connect';root.id='device-connect';const h=document.createElement('h1');h.textContent='FDUDash';const heading=document.createElement('h2');heading.textContent=tr('连接你的设备');const description=document.createElement('p');description.textContent=tr('校园密码和数据保存在你的设备，校园请求使用你的网络。');const download=document.createElement('a');download.className='secondary text-action';download.href=config.downloadURL;download.textContent=tr('下载 Windows 连接器');const steps=document.createElement('p');steps.textContent=tr('解压后运行 Start.cmd，获取一次性配对码。');const form=document.createElement('form'),label=document.createElement('label'),input=document.createElement('input');label.textContent=tr('配对码');input.inputMode='numeric';input.pattern='[0-9]{8}';input.maxLength=8;input.required=true;input.autocomplete='one-time-code';label.append(input);const button=document.createElement('button');button.textContent=tr('连接');const status=document.createElement('p');status.role='status';const note=document.createElement('p');note.className='module-note';note.textContent=tr('在当前设备运行连接器后，即可读取个人校园信息。');form.append(label,button);root.append(h,heading,description,download,steps,form,status,note);document.body.append(root);form.onsubmit=async e=>{e.preventDefault();button.disabled=true;status.textContent=tr('正在连接…');try{const response=await fetch(base+'/bridge/pair',{method:'POST',mode:'cors',credentials:'omit',targetAddressSpace:'loopback',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:input.value})});if(!response.ok)throw Error();const result=await response.json();localStorage.setItem(store,JSON.stringify({token:result.token,expiresAt:result.expiresAt}));location.reload();}catch{status.textContent=tr('无法连接，请启动本机连接器、允许浏览器访问本机网络，并检查配对码。');button.disabled=false;}};}
async function main(){applyLanguage();config=await fetch('/deployment.json',{cache:'no-store'}).then(r=>r.json());if(config.mode!=='cloud')throw Error('Invalid deployment mode');let device;try{device=JSON.parse(localStorage.getItem(store));}catch{}if(device?.token&&Date.parse(device.expiresAt)>Date.now()){try{const response=await fetch(base+'/api/session',{headers:{'X-FDUDash-Device':device.token},credentials:'omit',mode:'cors',targetAddressSpace:'loopback'});if(!response.ok)throw Error();globalThis.FDUDASH_DEVICE=Object.freeze({base,token:device.token});window.addEventListener('fdudash-device-disconnected',()=>{localStorage.removeItem(store);location.reload();});document.body.classList.remove('device-required');await import('./app.js');return;}catch{}}prompt();}
main().catch(()=>{document.body.textContent='FDUDash: '+tr('无法连接，请启动本机连接器、允许浏览器访问本机网络，并检查配对码。');});
